	/**
	 * Default Constructor
	 */
    public NetworkProfileService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new NetworkProfileEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(NetworkProfileRepository.class) );
		this.validator		= applicationContext.getBean(NetworkProfileValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		NetworkProfile
	 */
		public NetworkProfile createNetworkProfile( CreateNetworkProfileCommand command ) {

		NetworkProfile entity = new NetworkProfile();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setNetworkProfileId( command.getNetworkProfileId() );
            entity.setProfileName( command.getProfileName() );
            entity.setSsid( command.getSsid() );
            entity.setApn( command.getApn() );
            entity.setConnectivityType( command.getConnectivityType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of NetworkProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateNetworkProfileCommand
	 * @return		NetworkProfile
	 */
	public NetworkProfile updateNetworkProfile( UpdateNetworkProfileCommand command ) {

		NetworkProfile entity = new NetworkProfile();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setNetworkProfileId( command.getNetworkProfileId() );
            entity.setProfileName( command.getProfileName() );
            entity.setSsid( command.getSsid() );
            entity.setApn( command.getApn() );
            entity.setDevice( command.getDevice() );
            entity.setGateway( command.getGateway() );
            entity.setSimCard( command.getSimCard() );
            entity.setConnectivityType( command.getConnectivityType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of NetworkProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteNetworkProfileCommand
	 */
	public void delete( DeleteNetworkProfileCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getNetworkProfileId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of NetworkProfile {0} ", id );

	}

	/**
	 * Method to retrieve the NetworkProfile via NetworkProfileFetchOneSummary
	 * @param 	summary NetworkProfileFetchOneSummary
	 * @return 	NetworkProfileFetchOneResponse
	 */
	public NetworkProfile getNetworkProfile( NetworkProfileFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "NetworkProfileFetchOneSummary arg cannot be null" );

		NetworkProfile entity = null;
		UUID id = summary.getNetworkProfileId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a NetworkProfile using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all NetworkProfiles
	 *
	 * @return 	List<NetworkProfile>
	 */
    public List<NetworkProfile> getAllNetworkProfile() {
		List<NetworkProfile> list = projector.findAll( new FindAllNetworkProfileQuery() );
		return list;
	}

